# Plays generated test tones through SDL's disk audio driver and checks what actually came out: the pitch (by counting
# zero crossings), that a looped sound keeps playing without gaps, and that SoundPitch and ChannelPitch are in Hz.
# Usage: audio_output.py <blitzcc> <work directory>. Skipped (77) when the disk driver is not available.
import cmath
import math
import os
import shutil
import struct
import subprocess
import sys
import wave

blitzcc, work = sys.argv[1:3]
OPTIONS = os.environ.get("BLITZCC_OPTIONS", "").split()  # For example "-d", so that the test runs in Debug as well.
fixtures = os.path.dirname(os.path.abspath(__file__))
os.makedirs(work, exist_ok=True)
os.chdir(work)

OUTPUT_RATE = 44100  # What the disk driver is fixed to.
CYCLE = 50  # Samples of a period of the tone, so that the tone is a whole number of cycles and a loop has no seam.


def tone(name, rate, channels, bits, cycles=40, cycle=CYCLE):
	with wave.open(name, "wb") as out:
		out.setnchannels(channels)
		out.setsampwidth(bits // 8)
		out.setframerate(rate)
		frames = bytearray()
		for i in range(cycle * cycles):
			v = math.sin(2 * math.pi * i / cycle)
			frames += (struct.pack("B", int(128 + v * 100)) if bits == 8 else struct.pack("<h", int(v * 8000))) * channels
		out.writeframes(bytes(frames))
	return rate / cycle


def play(name, setup="", after="", loop=True, milliseconds=1500, classic=False):
	"""Plays a file and returns the left channel of what was sent to the disk driver."""
	with open("play.bb", "w") as source:
		source.write('s = LoadSound("%s")\n%s\n%s\nc = PlaySound(s)\n%s\nDelay %d\nDebugLog "playing " + ChannelPlaying(c)\n' % (name, "LoopSound s" if loop else "", setup, after, milliseconds))
	if subprocess.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	env.pop("BLITZ_AUDIO_CLASSIC", None)
	if classic:
		env["BLITZ_AUDIO_CLASSIC"] = "1"
	run = subprocess.run(["./play"], env=env, capture_output=True, timeout=60)
	if not os.path.exists("sdlaudio.raw"):
		print("no disk audio driver")
		raise SystemExit(77)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	samples = list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])
	return samples, run.stderr.decode(errors="replace")


failures = []


def check(what, condition):
	print(("ok   " if condition else "FAIL ") + what)
	if not condition:
		failures.append(what)


def analyze(samples):
	loud = [i for i, v in enumerate(samples) if abs(v) > 300]
	if not loud:
		return 0.0, 0.0, 0
	segment = samples[loud[0] + 4000 : loud[0] + 34000]
	crossings = [i for i in range(1, len(segment)) if segment[i - 1] < 0 <= segment[i]]
	frequency = OUTPUT_RATE * (len(crossings) - 1) / (crossings[-1] - crossings[0]) if len(crossings) > 2 else 0.0
	# A gap or a click is a jump the smooth tone does not have.
	d2 = [abs(segment[i + 1] - 2 * segment[i] + segment[i - 1]) for i in range(1, len(segment) - 1)]
	smoothness = max(d2) / max(1, sorted(d2)[len(d2) // 2])
	return frequency, smoothness, (loud[-1] - loud[0]) / OUTPUT_RATE


# Pitch of every kind of file, and that looping keeps it going for longer than the file is.
for rate in (8000, 11025, 22050, 44100, 48000):
	for channels in (1, 2):
		for bits in (8, 16):
			expected = tone("tone.wav", rate, channels, bits)
			samples, log = play("tone.wav")
			frequency, smoothness, length = analyze(samples)
			label = "%d Hz %d channel(s) %d bit" % (rate, channels, bits)
			check("%s: pitch %.1f Hz is %.1f Hz" % (label, frequency, expected), abs(frequency - expected) < expected * 0.01)
			check("%s: looped for %.2f s of a 0.09 s file" % (label, length), length > 1.0 and "playing 1" in log)
			check("%s: loop is gapless (jump %.1fx)" % (label, smoothness), smoothness < 4.0)

# The same file without looping ends by itself.
expected = tone("tone.wav", 22050, 1, 16)
samples, log = play("tone.wav", loop=False)
frequency, smoothness, length = analyze(samples)
check("one shot ends after %.2f s" % length, length < 0.5 and "playing 0" in log)

# SoundPitch and ChannelPitch are the frequency in Hz that the file is played at.
tone("tone.wav", 22050, 1, 16)
for what, setup, after, expected in (
	("SoundPitch 44100", "SoundPitch s, 44100", "", 882.0),
	("SoundPitch 11025", "SoundPitch s, 11025", "", 220.5),
	("ChannelPitch 44100", "", "ChannelPitch c, 44100", 882.0),
	("ChannelPitch 11025", "", "ChannelPitch c, 11025", 220.5),
):
	samples, log = play("tone.wav", setup, after)
	frequency, smoothness, length = analyze(samples)
	check("%s: pitch %.1f Hz is %.1f Hz" % (what, frequency, expected), abs(frequency - expected) < expected * 0.01)

# BLITZ_AUDIO_CLASSIC resamples like the original (linear interpolation), which keeps the pitch but adds the mirror images of a low-rate
# sound above its own bandwidth. SDL_mixer's own resampling leaves them out.
def image_energy(samples):
	loud = [i for i, v in enumerate(samples) if abs(v) > 300]
	segment = samples[loud[0] + 4000 : loud[0] + 4000 + 16384]
	# A coarse DFT at the tone itself and at frequencies where only mirror images can be.
	def power(frequency):
		w = -2j * math.pi * frequency / OUTPUT_RATE
		return abs(sum(v * cmath.exp(w * i) for i, v in enumerate(segment[:4096]))) ** 2
	tone_power = power(3000.0)
	image_power = power(9000.0)
	return image_power / tone_power


expected = tone("tone.wav", 12000, 1, 16, cycles=400, cycle=4)
clean_samples, log = play("tone.wav")
classic_samples, log = play("tone.wav", classic=True)
frequency, smoothness, length = analyze(classic_samples)
check("classic: pitch %.1f Hz is %.1f Hz" % (frequency, expected), abs(frequency - expected) < expected * 0.01)
check("classic: looped for %.2f s" % length, length > 1.0)
clean, classic = image_energy(clean_samples), image_energy(classic_samples)
check("classic adds images above the file's bandwidth (%.5f vs %.5f)" % (classic, clean), classic > clean * 10)

# Doppler: a sound that comes from an entity is shifted in pitch when the entity or the listener moves. Both are moved a unit
# every 50 ms (about 20 meters per second), toward or away from each other along Z.
def play_moving(listener_step, source_step, scale=1.0, distance=1.0, name="tone.wav"):
	body = (
		's = Load3DSound("%s")\nLoopSound s\nlistener = CreatePivot()\nsource = CreatePivot()\nPositionEntity source, 0, 0, 100\n'
		"CreateListener listener, 0, %f, %f\nc = EmitSound(s, source)\n"
		"For i = 1 To 30\n\tMoveEntity listener, 0, 0, %f\n\tMoveEntity source, 0, 0, %f\n\tDelay 50\nNext\n"
		'DebugLog "playing " + ChannelPlaying(c)\n'
	) % (name, scale, distance, listener_step, source_step)
	with open("play.bb", "w") as source:
		source.write(body)
	if subprocess.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	subprocess.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	return samples_after(list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2]), 0.9, 0.4)


def crossings_frequency(segment):
	crossings = [i for i in range(1, len(segment)) if segment[i - 1] < 0 <= segment[i]]
	return OUTPUT_RATE * (len(crossings) - 1) / (crossings[-1] - crossings[0]) if len(crossings) > 2 else 0.0


def samples_after(samples, start, length):
	"""The pitch of a stretch of the sound, from `start` seconds after it got loud, so that the shift has settled."""
	loud = [i for i, v in enumerate(samples) if abs(v) > 300]
	first = loud[0] + int(start * OUTPUT_RATE)
	return crossings_frequency(samples[first : first + int(length * OUTPUT_RATE)])


expected = tone("tone.wav", 22050, 1, 16)
for what, listener_step, source_step, scale, distance, low, high in (
	("standing still", 0, 0, 1.0, 1.0, 0.99, 1.01),
	("source moving away", 0, 1, 1.0, 1.0, 0.90, 0.97),
	("source moving toward the listener", 0, -1, 1.0, 1.0, 1.03, 1.12),
	("listener moving toward the source", 1, 0, 1.0, 1.0, 1.03, 1.12),
	("listener moving away from the source", -1, 0, 1.0, 1.0, 0.90, 0.97),
	("both moving the same way", 1, 1, 1.0, 1.0, 0.99, 1.01),
	("doppler scale 0", 0, 1, 0.0, 1.0, 0.99, 1.01),
	("doppler scale 2 shifts twice as far", 0, 1, 2.0, 1.0, 0.80, 0.94),
	("distance scale 0.5 halves the speeds", 0, 1, 1.0, 0.5, 0.95, 0.99),
):
	frequency = play_moving(listener_step, source_step, scale, distance)
	check("doppler, %s: %.1f Hz is %.2f to %.2f of %.1f Hz" % (what, frequency, low, high, expected), expected * low < frequency < expected * high)

# The shift is smooth: a source that stands still and then drives off glides down in pitch, it does not jump.
def play_start_stop():
	body = (
		's = Load3DSound("tone.wav")\nLoopSound s\nlistener = CreatePivot()\nsource = CreatePivot()\nPositionEntity source, 0, 0, 100\n'
		"CreateListener listener, 0, 1, 1\nc = EmitSound(s, source)\n"
		"For i = 1 To 10\n\tDelay 50\nNext\n"
		"For i = 1 To 40\n\tMoveEntity source, 0, 0, 3\n\tDelay 50\nNext\n"
	)
	with open("play.bb", "w") as source:
		source.write(body)
	if subprocess.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	subprocess.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	return list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])


samples = play_start_stop()
loud = [i for i, v in enumerate(samples) if abs(v) > 300][0]
window = int(0.04 * OUTPUT_RATE)
pitches = [crossings_frequency(samples[loud + i * window : loud + (i + 1) * window]) for i in range(1, 44)]
pitches = [p for p in pitches if p > 0]
steps = [abs(pitches[i + 1] - pitches[i]) / expected for i in range(len(pitches) - 1)]
check("doppler glides: the pitch goes from %.1f to %.1f Hz, the largest step between 40 ms is %.1f%%" % (pitches[0], min(pitches), max(steps) * 100), pitches[0] > expected * 0.98 and min(pitches) < expected * 0.93 and max(steps) < 0.08)

# The sound of movies (OpenMovie), which plays on a stream of its own: a tone of 440 Hz for 3 seconds in a movie of every format. The movies
# are the ones of tests/suite/movies, whose picture is not looked at here.
movies = os.path.join(os.path.dirname(fixtures), "suite", "movies")
for movie in ("colors.mpg", "colors.avi", "colors.mp4", "colors.webm"):
	shutil.copyfile(os.path.join(movies, movie), movie)
	with open("play.bb", "w") as source:
		source.write('m = OpenMovie("%s")\nDebugLog "opened " + m\nWhile MoviePlaying(m)\n\tDelay 20\nWend\n' % movie)
	if subprocess.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	run = subprocess.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read() if os.path.exists("sdlaudio.raw") else b""
	count = len(data) // 4
	samples = list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])
	frequency, smoothness, length = analyze(samples)
	check("movie %s: pitch %.1f Hz is 440 Hz" % (movie, frequency), abs(frequency - 440.0) < 440.0 * 0.01)
	check("movie %s: sound lasts %.2f s of a 3 s movie" % (movie, length), 2.4 < length < 3.6)

# MovieVolume scales the sound of a movie, from silence to the full sound.
peaks = {}
for volume in ("1.0", "0.5", "0.0"):
	with open("play.bb", "w") as source:
		source.write('m = OpenMovie("colors.mp4")\nMovieVolume m, %s\nWhile MoviePlaying(m)\n\tDelay 20\nWend\n' % volume)
	if subprocess.run([blitzcc, "play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	subprocess.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read() if os.path.exists("sdlaudio.raw") else b""
	count = len(data) // 4
	peaks[volume] = max([abs(v) for v in struct.unpack("<%dh" % (count * 2), data[: count * 4])] + [0])
check("MovieVolume: the peak is %d at 1, %d at 0.5 and %d at 0" % (peaks["1.0"], peaks["0.5"], peaks["0.0"]), peaks["1.0"] > 1000 and 0.45 < peaks["0.5"] / peaks["1.0"] < 0.55 and peaks["0.0"] < 10)

# Opus decodes at 48 kHz whatever the file was recorded at, so it has to be resampled to play at the right pitch. The fixtures are a
# 960 Hz tone (50 samples per cycle at 48 kHz) of half a second, as .opus (Ogg Opus) and as Opus packets in an .ogg file.
for fixture in ("tone.opus", "tone_in_ogg.ogg"):
	shutil.copyfile(os.path.join(fixtures, fixture), fixture)
	samples, log = play(fixture)
	frequency, smoothness, length = analyze(samples)
	check("%s: pitch %.1f Hz is 960 Hz" % (fixture, frequency), abs(frequency - 960.0) < 960.0 * 0.01)
	check("%s: looped for %.2f s of a 0.5 s file" % (fixture, length), length > 1.0 and "playing 1" in log)
	samples, log = play(fixture, loop=False)
	frequency, smoothness, length = analyze(samples)
	check("%s: one shot of %.2f s lasts as long as the 0.5 s file" % (fixture, length), 0.4 < length < 0.65 and "playing 0" in log)

sys.exit(1 if failures else 0)
